"""Original adult everyday-care and human-connection scenarios; no diagnostic scoring."""
from course_common import Course
from selfcare.curriculum import finish, revise
S={
 'care':('NIMH · Caring for Your Mental Health','https://www.nimh.nih.gov/health/topics/caring-for-your-mental-health'),
 'sleep':('CDC · About Sleep','https://www.cdc.gov/sleep/about/index.html'),
 'move':('WHO · Physical activity','https://www.who.int/news-room/fact-sheets/detail/physical-activity'),
 'food':('WHO · Healthy diet','https://www.who.int/news-room/fact-sheets/detail/healthy-diet'),
 'habits':('NIH · Physical Wellness Toolkit','https://www.nih.gov/health-information/your-healthiest-self-wellness-toolkits/physical-wellness-toolkit'),
 'stress':('WHO · Doing What Matters in Times of Stress','https://www.who.int/publications/i/item/9789240003927'),
 'social':('NIH · Social Wellness Toolkit','https://www.nih.gov/health-information/your-healthiest-self-wellness-toolkits/social-wellness-toolkit'),
 'chat':('UC Berkeley · Informational Interviews','https://www.career.berkeley.edu/start-exploring/informational-interviews/'),
 'questions':('Huang 等（2017）· Question-Asking Increases Liking','https://www.hbs.edu/ris/Publication%20Files/Huang%20et%20al%202017_6945bc5e-3b3e-4c0a-addd-254c9e603c60.pdf')}

c=Course('selfcare',S);C=c.C;O=c.O
c.chapter('自我照顾，从看见需要开始','先认识精力、处境与需要，练习适合自己的小行动。','区分自我照顾、消费与自我要求，能提出有条件的日常照顾方案。',['care','habits'])
C('需要与行动','累了，先买一套自律课程吗？','小岚这周连续加班，最困扰的是睡眠被挤压。她只有一小时可自由安排，哪份计划更直接回应当前需要？','先做：与同事明确今晚交接，留出休息时间|再看：休息后是否仍需要课程帮助','先做：用这一小时研究三套课程并下单|再看：等学完课程再决定怎样休息','根据具体需要选择行动；购买工具可以有帮助，但在这个场景中，保护已经不足的休息机会更直接。')
C('小步开始','一个忙碌周，怎样开始照顾自己？','小舟想改掉午后连续久坐的习惯，工作日常被打断。哪种起步更容易在实际环境中执行和调整？','动作：午饭收好餐具后，起身走动一小会儿|备选：忙时先站起来伸展，周末回看','动作：从明天起同时晨跑、备餐、冥想和写日记|备选：任何一项没完成就重新开始整套计划','把动作连接到已有情境，保留缩小版本和回看机会；起步不需要同时改变生活所有方面。')
C('观察而非标签','一张精力记录，应该写什么？','小禾想了解自己近期为何疲惫，但还没有足够线索。哪种记录更有助于下一步判断？','记录：大致睡眠、工作负担、活动和感受|解释：暂不下诊断，寻找可讨论的变化','记录：每天给自己打“懒惰程度”分数|解释：只要分数高，就认定是意志力差','先记录可观察的处境与感受，避免用人格标签代替解释；记录不能直接诊断疲惫原因。')
C('适配资源','别人的早起计划，可以直接照搬吗？','一位轮班工作者看到朋友清晨六点的健康计划，想改善自己的生活。哪种调整更尊重现实条件？','保留：休息与适度活动的目标|调整：根据班次、照护安排和身体情况选择时段','保留：每天六点起床这一形式|调整：压缩夜班后的睡眠来完成相同安排','可以借鉴目标，不必复制时钟；工作、照护、身体条件不同，需要不同的落实方法。')
O('需要盘点','把“我要对自己好一点”说具体','小宁最近觉得生活只剩任务，但不确定最想改变哪一处。','用虚构或自己的例子，列出身体、情绪、关系中的两个需要，选一个本周可做的小行动，并说明为何优先。','回应题设即可：需要应能与处境对应，行动应在时间与资源内；可以选择休息、减少负担或寻求支持，不以行动数量评分。','处境：日程拥挤、精力有限|资源：本周有两段二十分钟空闲|约束：不要求披露病史或真实个人信息')
O('环境支持','让容易忘的事，更容易发生','小然想午休后短暂活动，却总在打开聊天软件后忘记。','设计一个环境提示、一个足够小的动作和一个忙碌日的备选方案，说明怎样知道它有没有帮助。','可以把提示放在已有动作之后，调整物品位置或日历；检查是否减少遗忘和负担，而不是用连续打卡证明个人价值。','线索：午休结束就打开电脑|难点：工作消息很多|目标：为活动留一点空间')
O('可恢复的计划','断了三天，怎样继续？','小路原本每晚散步，家中临时有事后中断三天，觉得计划已经失败。','写一段对自己的回应，再提出恢复或调整计划的一步，并说明何时可以继续暂停。','承认现实打断，把中断当调整信息；可以缩短、改时段或暂停，不需要补偿式加量，也不将困难解释为品格失败。','原计划：晚间散步|变化：出现照护事务|情绪：失望、担心坚持不下去')
O('求助与分工','不是所有负担都能靠自律解决','小澄一边全职工作一边照顾家人，休息常被临时安排占用。','提出一个自己能做的小调整和一个需要他人或组织支持的改变，并写出具体的求助说法。','把个人行动与结构性负担分开，可请求分担、替班或明确响应时段；无需把所有照护压力归咎于个人时间管理。','任务：工作与照护重叠|资源：有可商量的同事或家人|目标：保护一段实际可用的休息')
c.chapter('睡眠、休息与恢复','看时长，也看质量，为恢复留出真实机会。','能识别挤压睡眠的安排，区分日常调整与需要专业支持的困扰。',['sleep','care'])
C('睡眠机会','每天都困，先优化哪个环节？','小安通常凌晨一点睡、早上七点起，想先用手环把每段睡眠记录得更细。哪份安排更贴近已知问题？','先做：逐步为夜间留出更充足的睡眠机会|再看：记录白天状态和影响入睡的因素','先做：维持六小时睡眠，只比较设备分数|再看：分数上升后就不再关注困倦','对多数十八至六十岁成年人，CDC建议每日七小时或更多；设备分数不能替代足够睡眠机会与白天状态。个体需要和具体困扰仍需判断。')
C('持续困扰','睡够时间却总很疲惫，怎么办？','小林已留出充足睡眠时间，但连续数周睡不踏实并影响白天工作。哪种下一步更合适？','记录：睡眠情况与白天影响|支持：联系医疗专业人员讨论，而非自行诊断','记录：只看总时长已经足够|支持：认定一定是自己不够努力，继续硬撑','持续睡眠问题与日间影响值得向医疗专业人员咨询；课程和记录可以帮助描述情况，不能确认病因或替代评估。')
C('安排与取舍','晚上的 coffee chat，要约到几点？','一位朋友只方便深夜长聊，而你第二天要早起且最近休息不足。哪种回应兼顾关系与恢复？','回应：说明今晚不适合长聊，提议周末白天或短通话|边界：允许对方选择或婉拒','回应：担心失去机会，答应聊到很晚|边界：之后再靠自己压缩其他休息弥补','维持连接可以协商时段与形式；一次邀约不需要以持续牺牲已经不足的休息为前提。')
C('休息的效果','刷完手机更累，怎样调整休息？','小羽午后只有十五分钟，过去刷完工作群反而更紧绷。哪份实验更能检查这次休息是否有用？','尝试：暂离工作信息，做安静休息或轻松活动|观察：之后的紧绷感、精力与负担','尝试：继续刷同样的信息，并把十五分钟计为已休息|观察：只看是否按时结束','休息的形式需要看本人体验与当前需要；可以做低成本比较，不把所有离开任务的时间自动当恢复。')
O('睡前安排','为一个普通工作夜留出恢复','小莫下班较晚，睡前总处理零散消息，又希望第二天有精神。','安排一个现实的睡前收尾：包括停止处理消息的条件、可放下的任务、一个回看指标。','可用交接和消息边界保护睡眠机会，调整环境与时间；关注白天精神和入睡体验，不保证一次调整就能解决失眠。','约束：下班时间不完全可控|可控：部分消息和非紧急任务|目标：先改善一个夜晚的安排')
O('饮品与时段','coffee chat，一定要喝咖啡吗？','你喜欢认识新朋友，但发现晚间含咖啡因饮品可能影响自己入睡，对方提议下班后见面。','写出一种保留交流又照顾自己状态的安排，并给一段自然的解释。','可以选无咖啡因饮品、白天、散步或线上，直接说明偏好即可；coffee chat是交流形式，不要求饮咖啡或解释全部健康情况。','邀约：下班后咖啡馆|偏好：想认识对方|限制：不想影响夜间休息')
O('恢复边界','把休息时间说出口','你周六原本留作恢复，同事临时希望一起参加行业聚会，你愿意以后再去。','写一段友好而清楚的回应：说明这次选择，提供一个真心愿意的替代，保留拒绝空间。','可以明确本次不参加，提出其他时段或以后再联系；不必编造紧急事故，也不需要为合理休息提供长篇辩护。','原安排：周六休息|关系：希望保持友好|真实意愿：这次不去，以后可考虑')
O('适度观察','设备提醒，不等于诊断','小沐的设备连续给出低睡眠分数，因此越来越担心，每晚反复查看。','提出一种减少分数焦虑的使用方式，并说明出现什么实际影响时应考虑找专业人员。','把设备当有限线索，可减少查看频率、记录实际状态；持续困扰或日间功能受影响应咨询专业人员，不用设备分数自行诊断。','信息：可穿戴设备估计值|体验：反复查看后更担心|未知：设备误差与实际睡眠情况')
c.chapter('活动、饮食与日常健康','从生活环境与可做的改变开始，减少全有全无。','能比较适度活动与饮食安排，不追求统一体型或极端方案。',['move','food','habits'])
C('活动不只在健身房','没空完整锻炼，还能做什么？','小和每周很难留出完整训练时间，但上下班有一小段可步行路程。哪种判断更合理？','起步：把合适的步行或其他可及活动融入生活|调整：根据能力逐步增加，不以一次是否练够否定小量活动','起步：等有连续一小时再开始|调整：碎片活动都不记录，因为不算运动','身体活动不只包括正式训练；从自己能做的量开始有意义，进一步安排应适合身体情况与环境。')
C('减少久坐','周末运动，就不用管工作日了吗？','小元周末会运动，但工作日常连续坐几个小时。哪种修改更完整？','保留：喜欢的周末活动|补充：在工作日安排可行的起身与活动机会','保留：周末活动|补充：只增加周末强度，工作日继续连续久坐','规律活动和减少长时间久坐是相互补充的方向；不必用一次加量代替对日常环境的调整。')
C('多样而可持续','外卖也能做一个小调整吗？','小桥因工作常吃外卖，预算有限，希望改善搭配。哪份起步更符合多样与可持续的原则？','选择：在可负担选项中逐步增加蔬菜、豆类或其他多样食物|回看：是否方便、吃得满足、能持续','选择：把所有主食和油脂一次去掉|回看：只看限制了多少种食物','健康饮食关注充足、平衡、适度与多样，也需要结合预算、习惯和个人情况；限制越多不自动越健康。')
C('身体信号与专业支持','活动时疼痛，还要完成打卡吗？','小星刚开始活动，某动作引发明显疼痛，她担心停下来就算失败。哪种回应更妥当？','当下：停止引发疼痛的动作，不靠打卡硬撑|后续：根据情况寻求合适专业评估，再调整活动','当下：先完成规定数量|后续：把疼痛当作进步证明，继续增加强度','明显疼痛不应被打卡目标覆盖；无法仅凭题目判断原因，先避免硬撑，再按实际情况寻求专业帮助。')
O('可及的活动','设计一份不靠意志硬撑的活动计划','小葵久坐、预算有限，不喜欢跑步，也不想办健身卡。','提出一个喜欢或愿意尝试的活动、一个触发时机和一个忙时缩小版，并说明怎样调整。','活动可以是步行、舞蹈、家中活动或适配能力的其他形式；可行、适度且愿意持续，比指定某一运动更重要。','偏好：不喜欢跑步|资源：有限预算与零散时间|目标：增加日常活动机会')
O('食物选择','给一次工作午餐增加选择','你在固定食堂吃饭，可选菜不多，也不准备精确计算每一餐。','提出两种可轮换的搭配思路，说明如何兼顾多样、饱足、预算与已有饮食限制。','可结合可选主食、蔬菜和不同蛋白质来源轮换，不要求一种标准食谱；过敏、疾病或特殊需要应按个人专业建议处理。','场景：普通工作食堂|限制：选项与预算有限|目标：比原来多一点选择，不追求完美')
O('相伴活动','把连接和活动放在一起','你想和一位新认识的朋友再聊聊，两人都说最近久坐较多。','写一个轻松活动邀约，给出时间、可及性与天气备选，并允许对方选择静坐或线上。','可提出短距离散步或适合双方的活动，确认路线、时长和身体需求；不将活动能力当交友门槛，不承诺特定健康结果。','共同点：愿意继续交流|可能差异：体力、天气、出行方式|目标：双方都能舒适参加')
O('辨别承诺','一条“七天重启健康”的广告','有人推荐付费计划，声称统一菜单加高强度运动能让所有人七天恢复健康，不用再看医生。','指出至少两个需要核查的承诺，提出一个低风险的下一步，并说明需要何种专业支持时不应被广告替代。','可质疑适用于所有人、保证期限和替代医疗等主张；回到可靠信息与个人情况，选择适度行动，不自行停药或用课程替代评估。','主张：所有人、七天见效|方案：固定菜单与高强度运动|问题：缺少适用条件与证据')
c.chapter('情绪、压力与温柔的边界','给感受一点位置，也给求助和拒绝留出通道。','能区分倾听与建议，提出适当边界和支持路径。',['stress','care','social'])
C('感受与事实','“他们不回，我一定很讨厌”','小夏发出邀约一天未收到回复，开始认定别人都不喜欢自己。哪种回应更能保留判断空间？','辨认：我感到失落，但还不知道对方未回复的原因|行动：先照顾情绪，再决定是否适度跟进','辨认：失落说明判断已经被证明|行动：立即连续发消息要求对方说明态度','感受是真实体验，却不等于对别人想法的充分证据；把体验与推断分开，有助于选择更合适的行动。')
C('倾听前先问需要','朋友诉苦，要马上给办法吗？','朋友说最近工作很累，你还不清楚他想得到什么。哪种开场更容易提供合适支持？','先问：你想让我先听听，还是一起想办法？|回应：根据他的需要与自己的能力继续','先做：立刻发一套自己的效率方法|回应：如果他不照做，就继续解释方法为何有效','可以先确认需要，避免把自己的有效经验直接套给对方；倾听、实际帮助与专业支持各有位置。')
C('有限的支持','每天深夜接电话，快撑不住了','朋友常深夜打来长电话，你在意他，但睡眠持续受影响。哪种回应更兼顾双方？','说明：我愿意关心你，但深夜无法长聊|协商：约合适时段，并一起考虑其他支持','说明：既然在意，就必须随时接电话|协商：先隐藏疲惫，等关系变好再说','支持需要可持续的边界；明确可提供的时间与形式，比承诺随时承担更有利于长期关系。紧急危险需要及时的现实援助。')
C('自助与求助','生活已经明显受影响，还只靠打卡吗？','一位学习者持续感到强烈困扰，已影响吃饭、休息和工作，普通自助办法没有改善。哪种下一步更合适？','方向：联系合适的医疗或心理健康专业人员|支持：请可信的人协助安排，不靠课程自行诊断','方向：继续增加自律任务，等完成所有打卡再求助|支持：先把困扰藏起来，避免给别人添麻烦','持续且明显影响日常功能的困扰值得专业支持；自助不能成为拖延求助或责备自己的理由。')
O('停一下再回应','在冲动发消息之前留一个间隙','你看到朋友聚会没有邀请自己，很想立刻发一长段指责。','设计一个短暂停顿，再写一句区分观察、感受与请求的消息；也可以说明这次先不发的理由。','可先把注意放回当下、给情绪时间，再描述看见的事、自己的感受与愿意了解的问题；不把猜测当定论，也不强迫立即沟通。','观察：看到一张聚会照片|感受：失落与生气|未知：聚会原因和对方安排')
O('说不的练习','拒绝一次不合适的请求','刚认识的人希望你周末免费花半天帮忙，你没有余力，但希望表达礼貌。','写一段明确拒绝，并提供至多一个自己确实愿意的替代；说明为什么不需要虚假承诺。','清楚表达做不到，感谢信任即可；有余力可给公开资源或建议，不必用新的过量承诺补偿拒绝。','关系：刚认识|请求：半天免费帮助|实际：周末没有余力')
O('支持地图','把所有需要都压在一个人身上吗？','小雨遇到困难只联系同一位朋友，朋友近期也很忙。','为虚构情境画一份文字支持地图：区分倾听、实际协助与专业问题，各给一种可寻求的支持及边界。','可从朋友、家人、同伴、社区或专业人员中选择，具体资源因人而异；地图是增加选择，不是要求每个人都拥有同样支持。','需要：有人听、有人帮忙、某些问题需专业处理|现状：主要依赖一人|目标：让支持更可持续')
O('不强求积极','怎样陪伴正在失落的人','朋友尝试新活动不顺利，说“今天真的很难过”，你希望鼓励他。','写一段不急于否定感受的回应，问一个温和问题，并说明什么支持是你能提供的。','可承认失落、询问想说哪部分、提供有限而具体的陪伴；不要求马上乐观，也不把一次失败解释成永久能力不足。','情境：第一次尝试不顺|感受：失落|目标：尊重体验，保留下一步选择')
c.chapter('关系质量与日常连接','不比朋友数量，练习真实、互相尊重的关系。','能识别支持性关系，兼顾已有联系、新连接与独处。',['social','care'])
C('质量与数量','通讯录更多，就一定更有连接感吗？','小远添加了很多群和联系人，却觉得没人能认真交流。哪份调整更回应他的需要？','关注：选一两段愿意互相回应的关系|行动：安排一次有内容的交流，观察真实体验','关注：继续比较联系人数|行动：尽快加入更多群，以数量证明关系改善','联系人数量不能独自代表支持、信任与被理解；先明确缺少哪一种连接，再选择行动。')
C('具体的联系','“有空聚”怎样更容易落地？','你和老朋友都想见面，过去几次只停在“改天约”。哪条消息更便于双方做决定？','消息：这周六下午有空散步二十分钟吗？不方便也可下周|空间：允许对方改时间或拒绝','消息：我们一定得聚，你看着安排吧|空间：让对方猜时段、形式和期待','具体而轻量的提议可以减少安排成本，同时保留选择权；明确不等于要求对方配合。')
C('互相尊重','意见不同，怎样继续聊？','朋友喜欢热闹，你更喜欢安静，你们在商量周末活动。哪种回应更能推进共同安排？','回应：我想安静一点，你最想保留活动的哪部分？|安排：寻找双方能接受的形式或各自行动','回应：热闹的活动都没有价值，你应该改掉|安排：先证明自己的偏好更高级','偏好不同可以具体协商，无需给人格或生活方式排高低；也允许这次不一起活动。')
C('独处与连接','这周不想聚会，是不是不合格？','小鹿这周需要安静，但仍想保持与朋友的联系。哪种安排更尊重自主与关系？','选择：婉拒聚会，给朋友一条真诚消息或另约合适时间|标准：看双方需要与相处体验','选择：为了完成社交次数勉强参加|标准：只看本周是否见够规定人数','自我照顾不要求固定社交数量或外向表现；独处和连接可以按需要调整，关键是自主与适合自己的支持。')
O('主动关心','写一条不会压迫对方的近况消息','你想联系一位半年未见的朋友，不确定对方最近忙不忙。','写一条提到共同经历、表达关心且允许晚回的消息，避免要求对方马上汇报全部生活。','可以从一个具体想起对方的时刻开场，简短问候并留空间；不回复不自动意味着关系破裂。','关系：以前相处不错|间隔：半年|目标：重新打开一个轻松的联系通道')
O('共同活动','给不爱闲聊的人设计一种连接','两位朋友都想见面，但不喜欢坐着从头聊到尾，也不想花很多钱。','提出一种能一起做的小活动，说明如何给交流与安静都留空间，并设置可退出的时长。','可一起做饭、逛展、散步或参与可及活动；活动不需要高消费，关系也不以持续说话衡量。','偏好：有事情一起做|预算：有限|边界：各自精力与时间不同')
O('期待校准','“你怎么没有主动联系我”','你希望朋友多主动，对方却以为你们很久见一次也很亲近。','用一段不指责的表达说明自己的需要，询问对方习惯，再提出一个可试行的安排。','可描述自己何时感到失联，询问联络频率偏好，商量轻量安排；不把一种频率当友情的唯一标准。','你的期待：更常联系|对方理解：低频也信任|目标：协商，而不是考验')
O('参与社区','找一个会再见面的地方','刚搬到新城市的小书，希望慢慢认识人，不想每次都从大型陌生聚会开始。','选一个基于兴趣或共同任务、可重复参与的场景，设计第一次和第二次的小行动，并说明不合适时怎样退出。','可以选择社区活动、学习小组、志愿服务等，先做具体贡献或打招呼；重复参与只是机会，不保证建立友谊，也不要求强迫融入。','目标：认识附近的人|偏好：小规模、有共同活动|限制：每周时间有限')
c.chapter('破圈，从一个真实问题开始','走近陌生领域，观察不同生活，扩大理解的可能。','能把破圈目标转为具体问题，选择多样而可及的探索方式。',['social','chat'])
C('问题先于头衔','该约谁：名气最大，还是最相关？','你想了解社区书店如何选择活动主题，只有一次交流机会。哪种选择更贴近这个问题？','对象：实际策划或参与书店活动的人|准备：先看公开活动，带一个具体问题','对象：优先找完全无关领域的名人|准备：先问如何快速复制成功','选择与问题和实践经验有关的人，能更直接了解现场；头衔与名气不是唯一的交流价值。')
C('不同视角','只问与你很像的人，能了解全貌吗？','你已听过两位资深从业者介绍行业，想进一步了解日常工作差异。哪种下一步更能增加视角？','补充：在条件允许时听听不同阶段、岗位或地区的人|比较：注明各自处境，不强求统一结论','补充：只找经历与前两人相同的人|比较：把一致回答视为适用于所有人的证明','增加有意义的处境差异，有助于检验已有印象；不同经历是线索，不是代表全部人的样本。')
C('低门槛接触','还不敢直接约陌生人，可以怎样开始？','小陶对城市自然观察感兴趣，但直接一对一邀约让她压力很大。哪种起步仍符合探索目标？','起步：参加一次有组织的小型公开活动，先听再问一个问题|余地：也可先线上了解，再决定下一步','起步：必须立刻约行业前辈单独见面|余地：做不到就说明不适合破圈','探索可以通过公共活动、共同任务和线上交流逐步发生；不把高强度陌生社交当唯一入口。')
C('经验与普遍规律','一次聊天，足够决定转行吗？','你听一位自由职业者讲了很精彩的经历，很想马上辞职。哪种理解更审慎？','收获：记下适合自己追问的线索|验证：补查不同经历、收入波动和自己的条件，再做小实验','收获：成功经历已经证明这条路适合所有人|验证：先辞职，细节以后再问','个人经历可以打开可能，但无法独自证明普遍结果；重要决定应结合多方信息和自己的现实约束。')
O('好奇清单','把“想认识有趣的人”变具体','你想走出熟悉圈子，却不知道应该找谁聊。','选两个陌生领域，各写一个自己真正在意的问题，并说明什么经历的人可能帮助你理解它。','可以从生活、社区、手艺、科学或服务等领域切入，不要求职业收益；问题具体且真诚，比把人分成高价值低价值更重要。','起点：只有模糊的破圈愿望|资源：可接触公开活动与公开资料|目标：先形成可讨论的问题')
O('探索阶梯','给一次陌生领域尝试安排三小步','你对纪录片声音工作感兴趣，但完全没有相关朋友。','设计三步由浅到深的探索：至少包含一次公开资料了解、一次可及接触，以及一个尊重拒绝的邀约选择。','可先看公开工作介绍，再参加讲座或提问，之后视双方意愿约短聊；步骤可调整，不以必须见到某人作为成功条件。','兴趣：纪录片声音工作|现状：没有行业熟人|时间：两周内只能投入少量精力')
O('不预设对方','怎样问一位与你生活很不一样的人','你第一次认识一位社区维修师，想了解他的工作，却担心用自己的职业标准替他下结论。','写两个不带优劣预设的开放问题，并给一个当自己听到陌生术语时的追问。','可问具体一天、困难、选择或值得珍惜的部分，不把某种收入、学历或工作节奏当唯一尺度；术语不懂可以坦诚请解释。','对象：社区维修师|你的经验：主要在办公室工作|目标：理解不同日常，而不是替人评判')
O('从印象到实验','把一次聊天变成一个可验证的小尝试','听完城市种植爱好者的分享，你很想判断自己是否也喜欢。','设计一次低成本尝试，说明观察什么、保留什么未知，以及怎样向对方反馈而不要求长期指导。','可以先参加一次活动或照顾一种适合环境的植物，观察兴趣、时间与条件；一次尝试不是身份考试，后续请求需再次征得同意。','收获：对一项陌生爱好产生兴趣|限制：空间和预算有限|目标：用实际体验补充聊天印象')
c.chapter('Coffee chat：邀约与准备','把来意、时长和选择说清楚，让邀请轻而具体。','能写出尊重时间、便于拒绝且有明确学习目标的邀约。',['chat','social'])
C('具体来意','哪封邀约让对方更容易回应？','你读过一位博物馆教育工作者的公开分享，想了解她如何设计亲子活动。哪种邀请更清楚？','说明：提到读过的分享与一个具体疑问|请求：询问是否愿意抽二十分钟交流，不方便也没关系','说明：只说一直很仰慕，希望深度交流|请求：让对方安排时间，并一次解答十个问题','简短说明来由、相关问题与有限请求，可以降低理解和安排成本；礼貌也包括允许对方拒绝。')
C('形式与可及性','见面前，应该确认哪些事？','双方愿意聊二十分钟，但一位要照顾孩子，另一位跨时区。哪种安排更利于真正落地？','确认：带时区的日期时段、时长和沟通形式|备选：线上或异步问题，允许改期','确认：只说周五晚上见|备选：默认双方城市时间相同，临时再联系','明确时区、时长和形式，能减少误会；coffee chat不必局限于线下咖啡馆。')
C('适度跟进','未回复，怎样处理才有分寸？','你发出一次清楚的邀请，一周还没收到回复，也没有紧急事项。哪种处理更尊重双方？','选择：如仍有需要，可简短跟进一次并说明不方便也没关系|之后：没有回应就停止追催，寻找其他途径','选择：每天追加不同平台的私信|之后：直到对方解释不回复的原因才停止','可以结合关系和情境做一次轻量跟进，但沉默不是继续追催的许可；对方无需证明拒绝的合理性。')
C('见面与自主','首次见面，地点让你不舒服怎么办？','刚认识的对象只愿在你不熟悉的私人空间见面，你希望交流但对此不安心。哪种回应更合适？','提议：公开场所、线上或其他双方都舒适的形式|决定：对方不同意，也可以不见','提议：先同意，免得显得不信任|决定：等到了现场再判断是否能退出','可以依据自己的舒适与安全需要选择形式并拒绝；探索新连接不要求放弃自主边界。')
O('邀约写作','写一封八十到一百二十字的邀请','你想请一位不同行业的人聊聊他的日常判断方法，彼此此前不熟。','写一段简短邀约，包含认识来由、一个具体问题、有限时长、形式选择和拒绝空间；不必填写真实姓名或联系方式。','表达清楚、请求适度即可，不按字数机械扣分；不夸大关系、不暗藏推销，不把拒绝设计成让人内疚的选项。','关系：通过公开分享认识|目的：了解一种不同的工作经验|限制：不索要私人资料或免费长期指导')
O('准备而不背稿','为二十分钟准备一张小卡','对方已经答应与你聊社区活动策划，你查到他的公开介绍。','准备一个开场、三个有顺序的问题和一个可放弃的问题，并说明如何避免把聊天变成问卷。','可先确认目标，再从具体经历走向判断与建议；问题是路标而非考卷，允许跟随回答、删减问题并按时结束。','已知：对方的公开背景|时长：二十分钟|目标：了解实际工作，而非搜集履历')
O('期待与透明','想问求职建议，要不要伪装成纯交朋友？','你既想了解行业，也希望获得一点求职方向建议，暂时不准备请求内推。','写一段坦诚说明目的的邀请，并说明如果以后想请求内推，需要怎样另行沟通。','可以直接说正在探索行业与求职方向，不把谈话包装成别的目的；内推或其他帮助应另行明确请求，允许拒绝，不预设对方义务。','真实目的：行业了解与求职方向|当前请求：短聊和经验|边界：不默认获得职位或内推')
O('变化时的体谅','临时改期，怎样让对方少费心？','你已经约好明晚聊天，但突然有一项无法推迟的安排。','写一段尽早告知、简要道歉并提供可选时段的消息，同时允许对方取消；说明如何避免重复失约。','及时说明变更、承担安排成本，给有限备选即可；不用披露私密原因，不要求对方必须迁就，后续应检查自己的可用时间。','原约定：明晚二十分钟|变化：不可推迟的安排|目标：尊重对方时间，诚实调整')
c.chapter('Coffee chat：倾听、追问与表达','用具体经历打开话题，用回应让对话往前走。','能练习开放问题、跟随追问、复述确认与适度自我表达。',['questions','chat','social'])
C('追问实际经历','听到“那次很难”，怎样接话？','对方说第一次办社区活动很困难，你想理解具体发生了什么。哪句回应更能接住他的经历？','追问：当时最难的是哪一段？你怎么决定先处理什么？|态度：留意对方是否愿意继续','追问：你是不是因为经验不足才失败？|态度：先宣布自己的解释，再要求对方确认','跟随对方已表达的经历追问，通常比预设原因更能体现回应；研究不保证任何一句话都会得到好感，仍需看当事人的意愿。')
C('复述确认','“所以你讨厌团队合作？”','对方说跨部门协调很耗精力，你还不清楚他想表达什么。哪种复述更准确且开放？','复述：听起来协调成本是难点，我理解对吗？|追问：哪些合作方式反而有帮助？','复述：所以你就是不喜欢与人合作|追问：为什么不干脆自己做？','复述应保留不确定，允许对方修正；不要把具体困难扩大成人格或整体偏好判断。')
C('轮流与节奏','准备的问题，要全部问完吗？','二十分钟已经过去十五分钟，对方刚提到一个你很感兴趣的转折。哪种处理更尊重这次交流？','调整：围绕转折做一个相关追问|收尾：留时间总结，放弃其余非必要问题','调整：赶紧连续念完剩下的问题|收尾：默认聊不完就延长时间','提纲用于支持理解，不能覆盖倾听和已约定时长；可以删减问题，把重要线索留到获得同意后的以后。')
C('分享而不抢走话题','对方经历让你想到自己的故事','对方刚讲到一次团队冲突，你有相似经历很想分享。哪种接法更能保持双向交流？','接法：先回应对方，再简短分享相关一段，问是否愿意听|回到：继续请对方说他的判断','接法：立即用自己的长故事替换话题|回到：等讲完所有细节再考虑原来的问题','自我表达可以建立联系，但应与对方的话相关、长度适度并保留轮流机会；倾听不是完全不能分享。')
O('问题改写','把一个宽泛问题改成三个好问题','你原本只准备问：“你能介绍一下整个行业吗？”对方只有二十分钟。','改写成一个具体经历问题、一个判断问题和一个可由初学者尝试的问题，并解释为何这样排序。','可以从最近一次任务入手，再问如何取舍、最后问怎样低成本了解；不要求某种固定句式，重点是对方能回答且与你的目标相关。','原问题：介绍整个行业|对象：做过具体项目的人|限制：二十分钟')
O('听见细节','为一句回答写两个自然追问','对方说：“我以为大家需要更丰富的活动，后来才发现他们更希望有固定的见面时间。”','先用一句话确认自己的理解，再写两个跟随回答的追问；避免把它变成对所有人都成立的规律。','可追问如何发现、有什么证据、如何调整安排；先理解这次具体经验，再讨论其他条件，不把单次故事包装成通用公式。','转折：丰富活动与固定时间的取舍|未知：对象是谁、如何观察|目标：理解判断过程')
O('沉默与节奏','对方停顿了，要立刻填满吗？','你问完一个经历问题，对方安静了几秒，似乎在组织想法。','提出一种给思考留空间的回应，以及一种对方不想回答时的换题方式。','可以稍等、温和确认是否需要换角度，允许跳过；不把短暂停顿立刻解释成尴尬或拒绝，也不要求对方披露不愿说的内容。','情境：提问后短暂安静|可能：思考、疲惫或不想回答|目标：尊重节奏，避免逼问')
O('表达自己','三十秒介绍，不用把人生讲完','你第一次和一位陌生领域的朋友聊天，希望让他知道你是谁、为什么好奇。','写一段简短介绍，包括当前在做的事、真正好奇的问题、与本次交流的联系；不要求真实个人资料。','用具体且自然的表达即可，可以是爱好或生活探索而非职业；不按头衔、收入或表达外向程度评分。','场景：短聊开场|任务：给对方必要背景|边界：不用过度暴露隐私，也不编造身份')
c.chapter('差异、互惠与有分寸的交流','尊重隐私与拒绝，连接不必变成资源交换。','能处理术语差异、敏感问题、互惠和关系边界。',['social','chat','questions'])
C('坦诚不懂','听不懂一个术语，装懂更好吗？','对方解释工作时提到陌生术语，你想继续理解，又怕显得基础差。哪种回应更有助于这次交流？','回应：这个词我不熟悉，可以用一个具体例子说明吗？|准备：之后再查基础资料，不让对方补完所有知识','回应：假装听懂并不断附和|准备：依据猜测继续追问，避免暴露不懂','可以坦诚指出一个不懂的点，请求具体例子，同时承担基本准备；交流不是知识考试。')
C('敏感信息','想了解行业收入，怎么问？','你关心一种工作的收入稳定性，但与对方第一次见面。哪种问法更有分寸？','问题：如果方便，能聊聊常见收入结构或波动因素吗？不必说个人数字|后续：接受对方不回答','问题：先要求对方展示个人工资或合同截图|后续：把不愿分享解释为不真诚','可以询问一般结构与影响因素，并允许跳过；个人薪资、合同和隐私资料不是一次交流的必要交换。')
C('互惠不等于等价交易','自己没有行业资源，还能回馈吗？','对方耐心分享，你没有相应职业资源，担心“没价值”。哪种理解更健康？','回馈：认真准备、守时、感谢，遇到合适的公开资料再分享|边界：不必立刻用昂贵礼物或承诺抵债','回馈：只有资源相当才配交流|边界：先承诺以后随时免费帮忙，证明值得认识','互惠可以是认真回应与合适的小帮助，不要求即时等价交换；不应靠过量承诺或资源排名衡量人的价值。')
C('转介绍与同意','朋友给了另一个人的私人号码','你想认识对方提到的一位同行，但还不知道那位同行是否愿意联系。哪种下一步更尊重双方？','做法：请朋友先询问是否愿意被介绍，或提供公开联系渠道|边界：未经同意不转发私人资料','做法：直接把号码拉入陌生群，方便大家交流|边界：只要自己动机友善就不必再问','介绍也需要当事人同意与适当的联系方式；方便和善意不能替代对他人隐私的尊重。')
O('差异中的好奇','听到与你相反的生活选择','对方主动选择较低收入但更稳定的节奏，你一开始难以理解。','写一句不带优劣预设的追问，说明你想了解的取舍，再写一种保留自己不同选择的表达。','可问对方重视什么、哪些代价可接受，理解不等于必须认同；不要把自己的发展指标当所有人的生活目标。','差异：收入与时间的取舍|目标：理解价值与条件|边界：不替对方诊断或纠正人生')
O('记录与隐私','想录下聊天方便复盘','你担心漏掉重点，希望录音或将聊天内容写成公开文章。','分别说明录音、私人笔记和公开发布需要怎样沟通；写一段对方可以轻松拒绝的请求。','录音与公开传播应事先征得明确同意，并说明范围；私人记录也应尽量少记敏感细节。对方只同意聊天，不自动同意训练材料、转发或公开署名。','用途：先私人复盘，可能之后写文章|信息：可能涉及个人与工作经历|目标：保留学习，同时尊重当事人')
O('不做隐性推销','聊天中发现对方可能需要你的服务','你原先约的是了解社区活动，聊到一半发现自己做的工具也许能帮忙。','写一段透明说明利益关系、先征询是否愿意听的转场，并给出对方不感兴趣时的回应。','可以清楚说自己与工具的关系，询问是否愿意听简短介绍；对方拒绝就回到原主题，不把学习邀约偷偷变成销售漏斗。','原约定：经验交流|新发现：你的工具可能相关|边界：不能默认对方愿意听推销')
O('修复小失误','不小心问了一个太私人的问题','你问完后发现对方明显犹豫，意识到可能触及隐私。','写一句承担失误、允许跳过的回应，再给一个更合适的问题；说明为什么不必要求对方安慰自己。','可简短道歉、撤回追问、转向一般经验，不解释一长串自我辩护；让对方决定继续还是换题。','信号：对方犹豫并想转移话题|你的判断：问题可能过界|目标：修复，而非逼迫原谅')
c.chapter('结束、跟进与可持续探索','把一次交流留成温暖的连接，再回到自己的生活。','能按时收尾、具体感谢、适度跟进，并制定有余地的探索计划。',['chat','social','habits'])
C('守约收尾','聊得很开心，也要看时间吗？','二十分钟已到，对方之后还有安排，你还有不少问题。哪种收尾更体贴？','收尾：提醒约定时间，简短总结一项收获并感谢|后续：如有需要，另问是否方便以后再联系','收尾：假装没看时间，继续追加问题|后续：直到对方明确打断才离开','遵守已约定时长是尊重的一部分；聊得投机也不自动获得延长或长期指导的许可。')
C('具体感谢','感谢消息，怎样避免像群发模板？','对方分享了活动策划中的一次失败和调整，你想次日表达谢意。哪条消息更贴近这次交流？','内容：谢谢你讲到先测试报名流程，我准备在小活动中试一下|请求：这次只表达感谢，不追加一串新任务','内容：你太厉害了，以后我有任何问题都会找你|请求：请立刻再帮我看完整方案','具体指出收获与自己的下一步，可以体现认真倾听；感谢不应顺手变成未经协商的持续请求。')
C('经验与验证','照着建议做，还要看自己的条件吗？','你收到一个很有启发的活动建议，但你的预算和参与者年龄都不同。哪种行动更稳妥？','行动：先做适合自己条件的小规模测试|记录：区分对方原话、自己的理解和实际结果','行动：原样复制并宣布一定成功|记录：若无效就认定分享者说谎','把建议放回自己的条件中验证；参考经验不意味着结果保证，也不意味着把全部责任交给建议者。')
C('关系的节奏','没有持续来往，这次就白聊了吗？','一次聊天让你理解了新领域，但后来没有继续联系，也没有获得合作机会。哪种复盘更合理？','看见：学到了什么、是否互相尊重、有没有值得尝试的线索|允许：有些交流就是一次愉快相遇','看见：没有内推或合作就不算收获|要求：必须把每次相遇发展成长久关系','交流可以带来理解、陪伴与新视角，不必都转化为关系资产；后续频率要看双方意愿。')
O('结束表达','把一段好聊天轻轻收好','你与一位陶艺爱好者约了二十分钟，时间到了，你很喜欢这次交流。','写一段收尾：提醒时间、确认一个收获、感谢，再询问是否方便将来分享一次尝试结果。','让对方容易结束，并把以后联系作为可拒绝的新请求；不用要求立即约下一次或承诺长期指导。','主题：第一次了解陶艺日常|状态：聊得投机但已到时间|目标：尊重约定，保留自然的连接')
O('复盘而不收集隐私','一次聊天，留下哪三条记录？','你想建立个人探索笔记，记住这次交流的收获，又不想把朋友变成资料库。','写三项值得保留的内容和两项应避免记录或传播的信息，再提出一个自己的下一步。','可记概念、问题、行动和已获同意的联系偏好，避免无关隐私和敏感原话；复盘服务自己的学习，而非给人排序或建立未经同意的人物档案。','用途：私人学习笔记|材料：一段自愿交流|原则：少记必要内容，不擅自传播')
O('不过度联系','有新进展，要不要立刻发十条消息？','你试了对方建议，取得一点进展，想分享，同时不知道对方最近是否有空。','写一条简短更新：说明做了什么、学到什么、无需立即回复；如有新问题，怎样另行询问是否方便？','短而具体的反馈可以表达感谢，新的时间或帮助请求应重新协商；不是每次更新都需要追求回应，也不用频繁刷存在感。','进展：完成一次小尝试|意愿：想感谢并分享|边界：对方没有答应长期辅导')
O('综合实践','给下个月留一份有余地的计划','你想同时照顾身体、维持已有关系，并了解一个陌生领域，但可用时间不多。','制定四周的轻量计划：各选一个自我照顾行动、已有关系联系和破圈尝试，写出一次 coffee chat 的问题、边界、备选与回看方法。','行动应符合资源，允许改为线上、公共活动或暂缓邀约；回看精力、理解与相处体验，不按认识人数或健康结果打分。医疗困扰和私人信息不作为交作业条件。','资源：每周少量可自由安排时间|方向：身体、已有关系、新视角|约束：保留恢复、拒绝与调整空间')

revise(c)
if __name__=='__main__':finish(c)
